const getName = () => window.location.pathname.split('/').pop().replace('.html', '') || chartsData[0].name;
let currentIndex = Math.max(0, chartsData.findIndex(c => c.name === getName()));

function updatePage() {
  const c = chartsData[currentIndex];
  const validSources = (c.sources || []).filter(s => s.text && s.text.trim() !== '');

  document.getElementById('page-title').textContent = c.title;

  const sInline = document.getElementById('source-inline');
  sInline.innerHTML = validSources.length 
    ? '<span class="source-label">Sources:</span> ' + 
      validSources.map(s => '<a href="' + s.link + '" target="_blank">' + s.text + '</a>').join(' · ')
    : '';

  document.getElementById('chart-image').src = 'SVG-PNG/' + c.svgFile;

  const url = 'https://1charts.github.io/CSC/' + c.name + '.html';
  const txt = encodeURIComponent(c.title + ' - via @CommodityCSC');

  document.getElementById('twitter-share').href = 'https://twitter.com/intent/tweet?url=' + url + '&text=' + txt;
  document.getElementById('fb-share').href = 'https://www.facebook.com/sharer/sharer.php?u=' + url;

  document.getElementById('prev-btn').style.display = currentIndex > 0 ? 'flex' : 'none';
  document.getElementById('next-btn').style.display = currentIndex < chartsData.length - 1 ? 'flex' : 'none';
  document.title = c.title + ' | CSC';

  makeTitleDraggable();
}

function navigateTo(idx) {
  if (idx < 0 || idx >= chartsData.length) return;
  currentIndex = idx;
  updatePage();
  history.pushState({index: currentIndex}, '', chartsData[currentIndex].name + '.html');
}

const navigatePrev = () => navigateTo(currentIndex - 1);
const navigateNext = () => navigateTo(currentIndex + 1);

document.addEventListener('keydown', e => {
  if (e.key === 'ArrowRight' || e.code === 'Space') { e.preventDefault(); navigateNext(); }
  if (e.key === 'ArrowLeft') { e.preventDefault(); navigatePrev(); }
});

let tsX = 0;
const area = document.getElementById('full-capture-area');
area.addEventListener('touchstart', e => {
  if (e.touches.length === 1) tsX = e.touches[0].screenX;
}, { passive: true });

area.addEventListener('touchend', e => {
  if (e.changedTouches.length === 1) {
    const dx = e.changedTouches[0].screenX - tsX;
    if (Math.abs(dx) > 60) {
      if (dx < -60) navigateNext();
      else if (dx > 60) navigatePrev();
    }
  }
});

window.onpopstate = () => {
  currentIndex = Math.max(0, chartsData.findIndex(c => c.name === getName()));
  updatePage();
};

// ====================== FIX LISTENER DUPLICATI ======================
let dragInitialized = false;

function makeTitleDraggable() {
  if (dragInitialized) return;
  dragInitialized = true;

  const titleGroup = document.querySelector('.title-group');
  if (!titleGroup || window.innerWidth >= 1280) return;

  let isDragging = false;
  let startX, startY, initialLeft, initialTop;

  titleGroup.style.position = 'absolute';
  titleGroup.style.zIndex = '50';
  titleGroup.style.cursor = 'grab';

  titleGroup.addEventListener('touchstart', (e) => {
    isDragging = true;
    const rect = titleGroup.getBoundingClientRect();
    startX = e.touches[0].clientX;
    startY = e.touches[0].clientY;
    initialLeft = rect.left;
    initialTop = rect.top;
    titleGroup.style.transition = 'none';
    titleGroup.style.cursor = 'grabbing';
  }, { passive: true });

  document.addEventListener('touchmove', (e) => {
    if (!isDragging) return;
    const dx = e.touches[0].clientX - startX;
    const dy = e.touches[0].clientY - startY;
    let newLeft = initialLeft + dx;
    let newTop = initialTop + dy;
    const maxLeft = window.innerWidth - titleGroup.offsetWidth - 10;
    const maxTop = window.innerHeight - titleGroup.offsetHeight - 10;
    newLeft = Math.max(10, Math.min(newLeft, maxLeft));
    newTop = Math.max(10, Math.min(newTop, maxTop));
    titleGroup.style.left = newLeft + 'px';
    titleGroup.style.top = newTop + 'px';
  }, { passive: true });

  document.addEventListener('touchend', () => {
    if (isDragging) {
      isDragging = false;
      titleGroup.style.cursor = 'grab';
      titleGroup.style.transition = 'left 0.15s ease, top 0.15s ease';
    }
  });
}

window.onload = () => { updatePage(); };

const toggleFullScreen = () => {
  if (!document.fullscreenElement) {
    document.documentElement.requestFullscreen();
  } else {
    document.exitFullscreen();
  }
};

// ====================== SCREENSHOT CON TESTO ALLINEATO + TOAST DARK ======================
function takeScreenshot() {
  const c = chartsData[currentIndex];
  const validSources = (c.sources || []).filter(s => s.text && s.text.trim() !== '');
  const img = document.getElementById('chart-image');

  const preload = new Image();
  preload.crossOrigin = "anonymous";
  preload.src = img.src;

  preload.onload = () => {
    const canvas = document.createElement('canvas');
    const ctx = canvas.getContext('2d');

    const WIDTH = 1450;
    const PADDING_X = 45;           // ridotto per allineare meglio a sinistra
    const PADDING_TOP = 55;
    const PADDING_BOTTOM = 70;
    const TITLE_HEIGHT = 78;
    const SUBTITLE_HEIGHT = 38;
    const SOURCES_HEIGHT = validSources.length ? 48 : 0;

    canvas.width = WIDTH;
    canvas.height = PADDING_TOP + TITLE_HEIGHT + SUBTITLE_HEIGHT + SOURCES_HEIGHT 
                    + preload.height * (WIDTH - 2 * PADDING_X) / preload.width 
                    + PADDING_BOTTOM;

    ctx.fillStyle = '#1E1E1E';
    ctx.fillRect(0, 0, canvas.width, canvas.height);

    ctx.fillStyle = '#f8fafc';
    ctx.font = '700 42px Inter';
    ctx.textAlign = 'left';
    ctx.fillText(c.title, PADDING_X, PADDING_TOP + 48);

    ctx.fillStyle = '#67e8f9';
    ctx.font = '600 30px Inter';
    ctx.fillText('commoditysupercycle.com', PADDING_X, PADDING_TOP + TITLE_HEIGHT + 26);

    if (validSources.length) {
      ctx.fillStyle = '#f8fafc';
      ctx.font = '500 22px Inter';
      ctx.fillText('Sources:', PADDING_X, PADDING_TOP + TITLE_HEIGHT + SUBTITLE_HEIGHT + 28);

      ctx.fillStyle = '#94a3b8';
      ctx.font = '500 22px Inter';
      ctx.fillText(validSources.map(s => s.text).join(' · '), PADDING_X + 95, PADDING_TOP + TITLE_HEIGHT + SUBTITLE_HEIGHT + 28);
    }

    const imgX = PADDING_X;
    const imgY = PADDING_TOP + TITLE_HEIGHT + SUBTITLE_HEIGHT + SOURCES_HEIGHT;
    const imgW = WIDTH - 2 * PADDING_X;
    const imgH = preload.height * (imgW / preload.width);

    ctx.drawImage(preload, imgX, imgY, imgW, imgH);

    const dataUrl = canvas.toDataURL('image/png');
    const link = document.createElement('a');
    link.download = c.name + '_CSC.png';
    link.href = dataUrl;
    link.click();

    showDownloadToast(c.name);
  };
}

// Toast scuro coerente con il tema del sito
function showDownloadToast(chartName) {
  let toast = document.getElementById('download-toast');
  if (!toast) {
    toast = document.createElement('div');
    toast.id = 'download-toast';
    toast.style.cssText = `
      position: fixed; bottom: 30px; left: 50%; transform: translateX(-50%);
      background: #1f2937; color: #e0f2fe; padding: 14px 24px; border-radius: 12px;
      font-family: 'Inter', sans-serif; font-size: 15px; z-index: 10000;
      box-shadow: 0 10px 25px rgba(0,0,0,0.5); white-space: nowrap; border: 1px solid #334155;
    `;
    document.body.appendChild(toast);
  }

  toast.textContent = `✅ Screenshot "${chartName}" salvato nella cartella Download`;
  toast.style.opacity = '1';

  setTimeout(() => {
    toast.style.transition = 'opacity 0.4s ease';
    toast.style.opacity = '0';
    setTimeout(() => toast.remove(), 600);
  }, 2800);
}
